import { Splitter } from '@absoluteui/components/splitter';

const pane = (text: string): HTMLElement => {
  const el = document.createElement('section');
  el.textContent = text;
  return el;
};
const right = document.createElement('div');
Splitter.create(right, { orientation: 'vertical', panes: [{ content: pane('Editor'), label: 'Editor', min: 120 }, { content: pane('Console'), label: 'Console', size: '30%', collapsible: true }] });
const host = document.createElement('div');
host.style.setProperty('block-size', '30rem');
document.body.append(host);
Splitter.create(host, { panes: [{ content: pane('Files'), label: 'Files', size: 220, min: 160 }, { content: right, label: 'Workspace' }] });

import { Splitter, type SplitterChangeDetail } from '@absoluteui/components/splitter';

const sidebar = document.createElement('nav');
sidebar.textContent = 'Folders';
const content = document.createElement('main');
content.textContent = 'Messages';
const host = document.createElement('div');
host.style.setProperty('block-size', '24rem');
document.body.append(host);
const saved = sessionStorage.getItem('mail-split');
const parsed: unknown = saved ? JSON.parse(saved) : null;
const sizes = Array.isArray(parsed) && parsed.every((n) => typeof n === 'number') ? parsed : null;
Splitter.create(host, {
  sizes,
  panes: [
    { content: sidebar, label: 'Folders', size: '25%', min: 160, max: '50%', collapsible: true },
    { content, label: 'Messages', min: 240 },
  ],
});
host.addEventListener('aui-change', (event) => {
  sessionStorage.setItem('mail-split', JSON.stringify((event as CustomEvent<SplitterChangeDetail>).detail.sizes));
});
